class AgeRange
    private define minimum as integer;
    private define maximum as integer;

    method constructor(aMinimum as integer, aMaximum as integer)
        this.minimum <- aMinimum;
        this.maximum <- aMaximum;
    endMethod

    public method IsInRange(age as integer) as integer
        if age >= this.minimum and age <= this.maximum then
            return 1;
        else
            return 0;
        endIf
    endMethod
endClass

algorithm ValidateAge
    define minimum as integer;
    define maximum as integer;
    define age as integer;
    define range as AgeRange;
    read minimum;
    read maximum;
    read age;
    range <- new AgeRange(minimum, maximum);
    write range.IsInRange(age);
endAlgorithm
